def shortest_path(graph, source, target):
    # Initialize distances to all nodes (including source and target) with infinity
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    # Initialize the priority queue (minimum heap) which consists of nodes
    # with their current distance from the source node in the format (distance, node)
    heap = [(0, source)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # Check if we found the target node
        if current_node == target:
            return (current_distance, [target])

        # If the node was already processed with a shorter path, ignore
        if current_distance > distances[current_node]:
            continue

        # Check all neighbors of the current node
        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # If a new shortest path is found, update the distance and push the neighbor node in the heap
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))

    # If no path is found to the target return infinity and None as a path
    return (float("inf"), None)
