def shortest_path(graph, source, target):
    from heapq import heappush, heappop
    import sys

    # Initialize the queue with the source node, distance 0, and a list containing just the source node
    queue = [(0, 0, [source])]

    while queue:
        # Extract the node with the smallest tentative distance (first element of tuple)
        tentative_distance, distance, path = heappop(queue)

        # If target node is found with a lower distance than any previously found, update the minimum distance and path
        if target in graph and tentative_distance >= (distance + graph[target][0][1]):
            if distance + graph[target][0][1] < sys.maxsize:
                return (distance + graph[target][0][1], path + [target])

        # If the specific node has been processed previously with a lower distance, skip it
        if tentative_distance in (sys.maxsize, -distance):
            continue

        # Consider all adjacent nodes, calculate tentative distances through this node
        for neighbor, weight in graph.get(path[-1], []):
            total_distance = distance + weight
            heappush(queue, (total_distance, -total_distance, path + [neighbor]))

    # If the queue is exhausted without finding the target node, return infinity and None
    return float('inf'), None
