import heapq

def shortest_path(graph, source, target):
    # Priority queue to hold (distance, node) pairs, starting with source node (0, source)
    pq = [(0, source)]
    # Dictionary to hold cost to reach each vertex (dis)
    dis = {node: float('inf') for node in graph}
    dis[source] = 0
    # Dictionary to hold the shortest path tree (parent)
    parent = {node: None for node in graph}

    while pq:
        dist, node = heapq.heappop(pq)

        if node == target:
            # Reconstruct the path when target is reached
            path = [target]
            while path[-1] != source:
                path.append(parent[path[-1]])
            path.reverse()
            return (dist, path)

        if dist > dis[node]:
            continue

        for neighbor, weight in graph[node]:
            new_dist = dist + weight
            if new_dist < dis[neighbor]:
                dis[neighbor] = new_dist
                parent[neighbor] = node
                heapq.heappush(pq, (new_dist, neighbor))

    # If target is not reachable, return infinity and None
    return (float('inf'), None)

