    def dijkstra(graph, start, end):
        # Node (weight, node)
        heap = [(0, start)]
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        visited = set()

        while heap:
            current_weight, current_node = heapq.heappop(heap)

            if current_node == end:
                return distances[end]

            if current_node in visited:
                continue
            visited.add(current_node)

            for neighbor, weight in graph.get(current_node, []):
                distance = current_weight + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(heap, (distance, neighbor))

        return distances[end]

    # If the target is not reachable, dijkstra will return float('inf')
    if dijkstra(graph, source, target) == float('inf'):
        return float('inf'), None
    else:
        return dijkstra(graph, source, target), [target]
