def shortest_path(graph, source, target):
    # We need to use a priority queue (or min heap) to have efficient retrieval of the node with the minimum distance.
    import heapq

    # Maintain a dictionary to hold the current shortest distance to a node
    dist_from_source = {node: float('inf') for node in graph}
    dist_from_source[source] = 0

    # Priority Queue
    queue = [(0, source)]

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        # Shortest distance to current_node has already been updated by a shorter path
        if current_node == target:
            # We reach target, so we update distance with the smallest distance that we have found to move.
            return (current_distance, [current_node])
        if current_distance > dist_from_source[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only update if we found a shortest path to current_node
            if distance < dist_from_source[neighbor]:
                dist_from_source[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    # If after exhausting the queue we have not reached target, it's unreachable
    return (float('inf'), None)

