    distances = {node: float('inf') for node in graph}
    predecessors = {node: None for node in graph}
    distances[source] = 0 

    # Dijkstra's algorithm
    def relax(node, potential_next_node, potential_weight):
        new_weight = distances[node] + potential_weight
        if new_weight < distances[potential_next_node]:
            distances[potential_next_node] = new_weight
            predecessors[potential_next_node] = node

    visited = set()
    open_list = [(0, source)]

    while open_list:
        current_distance, current_node = min(open_list)
        open_list.remove((current_distance, current_node))
        visited.add(current_node)

        if current_node == target:
            return (current_distance, list(predecessors_shortest_path(predecessors, source, target)))

        # Explore all neighbors
        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                relax(current_node, neighbor, weight)

                if neighbor not in distances or current_distance + weight < distances[neighbor]:
                    open_list.append((current_distance + weight, neighbor))

    return (float('inf'), None)

