    def dijkstra(graph, source, target):
        # Priority queue with step count and [node, path]
        queue = [(0, [source])]
        visited = set()

        while queue:
            (step, path) = heappop(queue)

            if path[-1] in visited:
                continue
            visited.add(path[-1])

            if path[-1] == target:
                return (step, path)

            for (neighbour, weight) in graph.get(path[-1], []):
                if neighbour in visited:
                    continue
                heappush(queue, (step + weight, path + [neighbour]))

        return (float("inf"), None)

    return dijkstra(graph, source, target)
